const b = $json.body || {};
const p = { ...b, ...(b.customData || {}) };
// La accion Custom API del bot manda los campos planos; el Webhook de un
// workflow de GHL los manda dentro de body.customData. Se aceptan las dos.
const direccion = String(p.direccion || p.direccion_envio || '').trim().replace(/\s+/g, ' ');
const contactId = p.contactId || p.contact_id || null;
// Una direccion sin numero no se puede geocodificar con precision de entrega:
// Google devolveria el centro de la colonia como si fuera la casa.
return [{ json: { direccion, contactId, valida: direccion.length >= 10 && /\d/.test(direccion) } }];

const g = $json || {};
const d = $('Leer la dirección').first().json;
const st = g.status;
if (st === 'ZERO_RESULTS') return [{ json: { ok: false, motivo: 'direccion_no_encontrada', direccion: d.direccion } }];
if (st !== 'OK' || !(g.results || []).length)
  return [{ json: { ok: false, motivo: 'google_error', detalle: g.error_message || st || 'sin respuesta' } }];

const r = g.results[0];
const loc = (r.geometry || {}).location || {};
const tipo = (r.geometry || {}).location_type || '';
const exacta = tipo === 'ROOFTOP' || tipo === 'RANGE_INTERPOLATED';
const salida = { direccion_normalizada: r.formatted_address || d.direccion,
  lat: loc.lat ?? null, lng: loc.lng ?? null,
  mapa: (loc.lat != null && loc.lng != null) ? 'https://maps.google.com/?q=' + loc.lat + ',' + loc.lng : null,
  confianza: exacta ? 'exacta' : 'aproximada', contactId: d.contactId };

// partial_match o APPROXIMATE = Google adivino. Se devuelve el candidato pero con
// ok:false, para que el bot vuelva a preguntar en vez de dar por buena una
// coordenada que cae a dos cuadras. El dato va igual: sirve para repreguntar.
if (r.partial_match === true || tipo === 'APPROXIMATE')
  return [{ json: { ok: false, motivo: 'direccion_ambigua', ...salida } }];
return [{ json: { ok: true, ...salida } }];

const b = $json.body || {};
const p = { ...b, ...(b.customData || {}) };
const modalidad = String(p.modalidad || p.modalidad_envio || '').trim().toLowerCase();
const num = (v) => (v === '' || v === null || v === undefined) ? null : Number(v);
const e = { contactId: p.contactId || p.contact_id || null,
  modalidad,
  sucursal:    String(p.sucursal    || p.sucursal_envio    || '').trim(),
  branch_code: String(p.branch_code || p.branch_code_envio || '').trim(),
  direccion:   String(p.direccion   || p.direccion_envio   || '').trim(),
  lat: num(p.lat), lng: num(p.lng),
  mapa: String(p.mapa || p.mapa_envio || '').trim() };

const faltan = [];
if (!e.contactId) faltan.push('contactId');
if (modalidad === 'sucursal') {
  if (!e.branch_code) faltan.push('branch_code');
  if (!e.sucursal) faltan.push('sucursal');
} else if (modalidad === 'domicilio') {
  // Se exigen lat/lng a proposito: obligan a que el domicilio haya pasado por
  // /geocodificar-domicilio y por el si del cliente antes de guardarse.
  if (!e.direccion) faltan.push('direccion');
  if (e.lat === null || e.lng === null || Number.isNaN(e.lat) || Number.isNaN(e.lng)) faltan.push('lat/lng');
} else {
  faltan.push('modalidad (sucursal | domicilio)');
}
if (!e.mapa && e.lat !== null && e.lng !== null) e.mapa = 'https://maps.google.com/?q=' + e.lat + ',' + e.lng;
return [{ json: { ...e, faltan, completo: faltan.length === 0 } }];

// Un solo pedido abierto por cliente, por diseno (N1 contesta pedido_en_curso si
// ya hay otro). Aun asi se ordena y se toma el mas reciente, como hace N5.
const ops = ($('GHL · pedidos del contacto').first().json.opportunities || []).slice()
  .sort((a, b) => String(b.createdAt || b.updatedAt || '').localeCompare(String(a.createdAt || a.updatedAt || '')));
const o = ops[0] || null;
const e = $('Leer el envío').first().json;
return [{ json: { ...e, opportunityId: o ? o.id : null, sin_pedido: !o } }];

parameters.jsonBody:
={{ JSON.stringify((() => {
  const e = $('Pedido abierto del contacto').first().json;
  const ids = {};
  for (const f of $('GHL · campos de la cuenta').first().json.customFields || []) {
    const k = String(f.fieldKey || '');
    if (k.startsWith('opportunity.')) ids[k.slice(12)] = f.id;
  }
  const esSuc = e.modalidad === 'sucursal';
  const datos = { modalidad_envio: e.modalidad,
    sucursal_envio:    esSuc ? e.sucursal : '',
    branch_code_envio: esSuc ? e.branch_code : '',
    direccion_envio:   esSuc ? '' : e.direccion,
    geo_envio:         esSuc ? '' : (e.lat + ',' + e.lng),
    mapa_envio:        e.mapa || '' };
  return { customFields: Object.entries(datos).map(([k, v]) => {
    if (!ids[k]) throw new Error('Falta el campo de oportunidad ' + k);
    return { id: ids[k], field_value: String(v) };
  }) };
})()) }}

={{ JSON.stringify((() => {
  const e = $('Pedido abierto del contacto').first().json;
  const ids = {};
  for (const f of $('GHL · campos de la cuenta').first().json.customFields || []) {
    const k = String(f.fieldKey || '');
    if (k.startsWith('contact.')) ids[k.slice(8)] = f.id;
  }
  const esSuc = e.modalidad === 'sucursal';
  const datos = { branch_code: esSuc ? e.branch_code : '',
    sucursal_ocurre: esSuc ? e.sucursal : '',
    servicio_envio: esSuc ? 'ground_do' : 'ground' };
  return { customFields: Object.entries(datos).filter(([k]) => ids[k])
    .map(([k, v]) => ({ id: ids[k], field_value: String(v) })) };
})()) }}
